    assert_eq!(
        ThermalConductivity::from_base(v).convert_to(ThermalConductivityUnit::WattPerMeterKelvin),
        ThermalConductivity::from_base(v).as_watts_per_meter_kelvin()
    );
    assert_eq!(
        ThermalConductivity::new(v, ThermalConductivityUnit::BtuPerHourFootFahrenheit),
        ThermalConductivity::from_btus_per_hour_foot_fahrenheit(v)
    );
    assert_eq!(
        ThermalConductivity::from_base(v)
            .convert_to(ThermalConductivityUnit::BtuPerHourFootFahrenheit),
        ThermalConductivity::from_base(v).as_btus_per_hour_foot_fahrenheit()
    );
